rel <- function(got, ref) max(abs(unname(got) - ref)) / max(abs(ref))
pure <- function(s, order, j) {
  which(vapply(param_tuple_indices(s, order), function(t) all(t == j),
               logical(1)))
}

test_that("autoregressive() keeps its accuracy as a partial autocorrelation nears 1", {
  s <- autoregressive(5, order = 2)
  for (cs in ar2_cases) {
    eta <- c(0, cs$z)
    j <- cs$j + 1L
    lab <- sprintf("z = (%g, %g)", cs$z[1L], cs$z[2L])
    expect_lt(abs(param_logdet(s, eta) - cs$logdet) / abs(cs$logdet), 1e-13,
              label = paste("logdet at", lab))
    gens <- list(param_dlogdet, param_d2logdet, param_d3logdet, param_d4logdet)
    for (n in 1:4) {
      got <- gens[[n]](s, eta)[[pure(s, n, j)]]
      expect_lt(abs(got - cs$dlogdet[n]) / abs(cs$dlogdet[n]), 1e-12,
                label = sprintf("logdet order %d at %s", n, lab))
    }
    expect_lt(rel(param_solve(s, eta), cs$prec), 1e-13,
              label = paste("precision at", lab))
    expect_lt(rel(param_d1(s, eta)[[j]], cs$cov_d1), 1e-12,
              label = paste("covariance derivative at", lab))
  }
})

test_that("autoregressive_inv() keeps its accuracy as a partial autocorrelation nears 1", {
  s <- autoregressive_inv(5, order = 2)
  for (cs in ar2_cases) {
    eta <- c(0, cs$z)
    j <- cs$j + 1L
    lab <- sprintf("z = (%g, %g)", cs$z[1L], cs$z[2L])
    expect_lt(rel(param_d1(s, eta)[[j]], cs$prec_d1), 1e-12,
              label = paste("order 1 at", lab))
    expect_lt(rel(param_d2(s, eta)[[pure(s, 2L, j)]], cs$prec_d2), 1e-12,
              label = paste("order 2 at", lab))
  }
})

test_that("ar1_inv() keeps its accuracy as the correlation nears 1", {
  s <- ar1_inv(5)
  gens <- list(param_d1, param_d2, param_d3, param_d4)
  for (cs in ar1_cases) {
    eta <- c(0, cs$z)
    for (n in 1:4) {
      expect_lt(rel(gens[[n]](s, eta)[[pure(s, n, 2L)]], cs[[paste0("d", n)]]),
                1e-13, label = sprintf("order %d at z = %g", n, cs$z))
    }
  }
})
